class Renderer:
    def render(self, data, format):
        raise NotImplementedError("Subclasses must implement this method")

class CSVRenderer(Renderer):
    def render(self, data, format):
        lines = []
        header = ','.join(data[0].keys())
        lines.append(header)
        for row in data:
            lines.append(','.join(str(v) for v in row.values()))
        return '\n'.join(lines)

class JSONRenderer(Renderer):
    def render(self, data, format):
        import json
        return json.dumps(data, indent=2)

class HTMLRenderer(Renderer):
    def render(self, data, format):
        rows_html = ''
        for row in data:
            cells = ''.join(f'<td>{v}</td>' for v in row.values())
            rows_html += f'<tr>{cells}</tr>'
        headers = ''.join(f'<th>{k}</th>' for k in data[0].keys())
        return f'<table><thead><tr>{headers}</tr></thead><tbody>{rows_html}</tbody></table>'

FORMAT_REGISTRY = {
    'csv': CSVRenderer(),
    'json': JSONRenderer(),
    'html': HTMLRenderer(),
}

class ReportGenerator:
    def generate(self, data, format):
        renderer = FORMAT_REGISTRY.get(format)
        if renderer is None:
            raise ValueError(f'Unknown format: {format}')
        return renderer.render(data, format)
